// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(c));
        vm.assume(caller != address(c));
        vm.assume(newOwner != address(0));
        address prevOwner = c.owner();

        bool oldOwnerChanged = (caller == prevOwner);
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) {
        } catch { }

        bool ownerChanged = (c.owner() != prevOwner);
        assertTrue(!ownerChanged || oldOwnerChanged);
    }
}
